import { useContext, useMemo, useState } from "react";
import { topWindowContext } from "../../utils/topWindow/topWindowContext";
import { getParentWindow } from "../../utils/getParentWindow";
import { useResize } from "../../commonHelpers/hooks/useResize";
const isTableUtil = (width) => {
    if (width > 640 && width <= 1024) {
        return true;
    }
    return false;
};
export const useTablet = () => {
    const { topWindow } = useContext(topWindowContext);
    const win = useMemo(() => topWindow || getParentWindow(window), [topWindow]);
    const [isTablet, setIsTablet] = useState(isTableUtil(win.innerWidth));
    useResize(() => {
        setIsTablet(isTableUtil(win.innerWidth));
    }, true);
    return isTablet;
};
